from pathlib import Path
import json,subprocess,time,os,hashlib
p=Path(__file__).resolve().parent;root=Path('REPOSITORY_DIRECTORY');prot=json.loads((p/'protocol.json').read_text()); results=[]
for case in prot['sample_plan']:
 arm=case['arm'];k=case['k'];t=case['threads'];fits=case['fits'];name=f'{arm}-k{k}-t{t}';ready=p/(name+'.ready');go=p/(name+'.go');options=f', threads({t})' if arm=='fereg' else ''
 source=f'''version 19
clear all
set more off
set processors {min(t,8)}
adopath ++ "{root}/stata"
adopath ++ "{root}/dist"
use "{p}/data.dta", clear
quietly {arm} y x1-x{k} {options}
file open ready using "{ready}", write text replace
file write ready "ready"
file close ready
capture confirm file "{go}"
while _rc {{
    sleep 10
    capture confirm file "{go}"
}}
forvalues r=1/{fits} {{
    quietly {arm} y x1-x{k} {options}
    assert e(N)==1000000 & e(df_r)=={1000000-k-1}
}}
mata: f=fopen("{p}/{name}.science","w");fput(f,invtokens(strofreal((st_matrix("e(b)"),vec(st_matrix("e(V)"))',st_numscalar("e(rss)")),"%24.17g")));fclose(f)
display "SAMPLE_FITS_COMPLETE"
exit, clear
'''
 (p/(name+'.do')).write_text(source);env=os.environ.copy()
 for key in list(env):
  if key.startswith('FEREG_'):env.pop(key)
 print('Starting',name,flush=True);started=time.monotonic()
 with (p/(name+'.stderr')).open('w') as out:
  proc=subprocess.Popen(['/Applications/Stata/StataMP.app/Contents/MacOS/stata-mp','-b','do',name+'.do'],cwd=p,stdout=out,stderr=subprocess.STDOUT,env=env)
  while not ready.exists():
   if proc.poll() is not None or time.monotonic()-started>30:raise RuntimeError('Stata did not reach ready')
   time.sleep(.05)
  with (p/(name+'.sampler-output')).open('w') as slog:
   sampler=subprocess.Popen(['/usr/bin/sample',str(proc.pid),str(case['sample_seconds']),'1','-file',str(p/(name+'.sample'))],stdout=slog,stderr=subprocess.STDOUT)
   time.sleep(.2);go.write_text('go\n');sample_rc=sampler.wait(timeout=30)
  rc=proc.wait(timeout=180)
 assert rc==0 and 'SAMPLE_FITS_COMPLETE' in (p/(name+'.log')).read_text()
 record={**case,'returncode':rc,'sample_returncode':sample_rc,'elapsed_seconds':time.monotonic()-started,'sample_sha256':hashlib.sha256((p/(name+'.sample')).read_bytes()).hexdigest() if (p/(name+'.sample')).exists() else None}
 results.append(record);(p/'sample-runs.json').write_text(json.dumps(results,indent=2)+'\n');print('Finished',name,record,flush=True)
